import{_ as o,c as e,o as s,ag as a}from"./chunks/framework.bCALENAD.js";const u=JSON.parse('{"title":"浏览器/网络问题","description":"","frontmatter":{},"headers":[],"relativePath":"interview/8part/browser&network.md","filePath":"interview/8part/browser&network.md","lastUpdated":1786609894000}'),d={name:"interview/8part/browser&network.md"};function n(i,t,l,r,c,p){return s(),e("div",null,[...t[0]||(t[0]=[a(`<h1 id="浏览器-网络问题" tabindex="-1">浏览器/网络问题 <a class="header-anchor" href="#浏览器-网络问题" aria-label="Permalink to &quot;浏览器/网络问题&quot;">​</a></h1><h2 id="三种会话保持机制" tabindex="-1">三种会话保持机制 <a class="header-anchor" href="#三种会话保持机制" aria-label="Permalink to &quot;三种会话保持机制&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">session 机制保持会话</p><p><strong>存在的问题</strong></p><ul><li>高并发情况下，会占用服务器大量内存。</li><li>分布式（一个业务分成几个子业务，部署在多个服务器）或者集群（一个业务部署在多个服务器）的时候，session 不能共享。</li></ul><p><strong>解决方案</strong></p><ul><li>高并发的时候可以将 session 存储到 redis，如果用户长时间没有访问，将 session 存储到 redis，就减少了服务器的压力。</li><li>分布式或者集群的时候，先通过 redis 来判断用户状态也可以实现 session 共享。</li></ul></div><div class="info custom-block"><p class="custom-block-title">cookie 机制保持会话</p><p><strong>使用方法</strong></p><ul><li>登录验证后，创建登录凭证（比如：用户 id + 登录时间 + 过期时间），将登录凭证进行加密（为了避免暴露信息），加密后写到浏览器的 cookie，以后每次请求都发送 cookie，服务器根据对应的解密算法对其进行验证（或者将加密过的 cookie 内容存储到数据库，请求服务器的时候，服务器在数据库进行查找）。</li></ul><p><strong>存在的问题</strong></p><ul><li>每次访问都提交 cookie，增加请求量。</li><li>其他访问可能需要 cookie（比如说购物车的信息存放在 cookie），浏览器对每个域存储的 cookie 的大小有限制，那么需要控制加密后的凭证。</li></ul></div><div class="info custom-block"><p class="custom-block-title">token 机制保持会话</p><p><strong>使用方法</strong></p><ul><li>cookie 和 session 依赖于浏览器，如果客户端不是浏览器，那么需要手动添加 token（和 cookie 类似，也是登录凭证），将 token 添加到 http header 或者作为参数添加到 url。</li></ul><p><strong>存在的问题</strong></p><ul><li>每次访问的时候手动添加 token。</li><li>和 cookie 的方式一样增加了请求量。</li></ul></div><h2 id="网络五层-七层模型" tabindex="-1">网络五层/七层模型 <a class="header-anchor" href="#网络五层-七层模型" aria-label="Permalink to &quot;网络五层/七层模型&quot;">​</a></h2><p><strong>五层模型：</strong></p><blockquote><p>物理层 → 数据链路层 → 网络层 → 传输层 → 应用层</p></blockquote><p><strong>七层模型：</strong></p><blockquote><p>物理层 → 数据链路层 → 网络层 → 传输层 → 会话层 → 表示层 → 应用层</p></blockquote><table tabindex="0"><thead><tr><th>层次</th><th>主要功能</th><th>数据单位</th><th>典型协议/设备</th></tr></thead><tbody><tr><td><strong>应用层</strong></td><td>为用户应用程序提供网络服务，如网页访问、邮件、文件传输、域名解析</td><td>报文 / 消息</td><td>HTTP、HTTPS、FTP、SMTP、DNS、SSH；代理服务器</td></tr><tr><td><strong>传输层</strong></td><td>提供端到端通信，负责分段、端口寻址、可靠传输或不可靠传输</td><td>报文段 / 数据段</td><td>TCP、UDP；防火墙、网关</td></tr><tr><td><strong>网络层</strong></td><td>负责逻辑寻址和路由选择，把数据从源主机送到目的主机</td><td>分组 / 数据包</td><td>IP、ICMP、ARP；路由器</td></tr><tr><td><strong>数据链路层</strong></td><td>负责相邻节点之间的帧传输、物理寻址、差错检测</td><td>帧</td><td>Ethernet、PPP、Wi-Fi；交换机、网桥</td></tr><tr><td><strong>物理层</strong></td><td>负责比特流在物理介质上的传输，定义电气、机械、功能特性</td><td>比特</td><td>网线、光纤、无线电波；集线器、中继器</td></tr></tbody></table><h2 id="强制缓存-和-缓存协商" tabindex="-1">强制缓存 和 缓存协商 <a class="header-anchor" href="#强制缓存-和-缓存协商" aria-label="Permalink to &quot;强制缓存 和 缓存协商&quot;">​</a></h2><p><strong>强制缓存</strong>与<strong>缓存协商</strong>是浏览器 HTTP 缓存机制的两种核心策略，分别对应<strong>强缓存</strong>和<strong>协商缓存</strong>。两者配合使用，能最大程度减少不必要的网络请求，提升页面加载速度。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请求资源</span></span>
<span class="line"><span>  ⬇️</span></span>
<span class="line"><span>强缓存是否命中？（Cache-Control / Expires）</span></span>
<span class="line"><span>  ├── 是 → 直接使用本地缓存（200 from cache）</span></span>
<span class="line"><span>  └── 否 → 发起请求，携带 ETag / Last-Modified</span></span>
<span class="line"><span>              ⬇️</span></span>
<span class="line"><span>        服务器比对</span></span>
<span class="line"><span>          ├── 资源未变 → 304 Not Modified（使用本地缓存）</span></span>
<span class="line"><span>          └── 资源已变 → 200 + 新资源 + 新缓存头</span></span></code></pre></div><h3 id="强缓存" tabindex="-1">强缓存 <a class="header-anchor" href="#强缓存" aria-label="Permalink to &quot;强缓存&quot;">​</a></h3><p>强缓存是指浏览器直接从本地缓存中读取资源，<strong>完全不向服务器发送请求</strong>。是否命中强缓存，由响应头中的两个字段控制：</p><ol><li><code>Cache-Control</code>（优先级更高）</li></ol><table tabindex="0"><thead><tr><th>值</th><th>含义</th></tr></thead><tbody><tr><td><code>max-age=3600</code></td><td>资源在 3600 秒内有效，直接使用缓存</td></tr><tr><td><code>no-cache</code></td><td>不使用强缓存，但<strong>会走协商缓存</strong>（注意：不是&quot;不缓存&quot;）</td></tr><tr><td><code>no-store</code></td><td>完全不缓存，每次都重新请求</td></tr><tr><td><code>public</code></td><td>允许浏览器和中间代理都缓存</td></tr><tr><td><code>private</code></td><td>仅允许浏览器缓存，代理不可缓存</td></tr></tbody></table><ol start="2"><li><code>Expires</code>（HTTP/1.0 遗留，优先级低于 Cache-Control）</li></ol><ul><li>指定一个绝对过期时间，如 <code>Expires: Wed, 13 Aug 2027 15:00:00 GMT</code></li><li>受客户端本地时间偏差影响，可靠性不如 <code>Cache-Control</code></li></ul><blockquote><p><strong>流程</strong>：浏览器判断强缓存是否过期 → 未过期则直接使用本地缓存（状态码 <code>200 from disk/memory cache</code>），不发起网络请求。</p></blockquote><h3 id="协商缓存" tabindex="-1">协商缓存 <a class="header-anchor" href="#协商缓存" aria-label="Permalink to &quot;协商缓存&quot;">​</a></h3><p>当强缓存失效（或设置了 <code>no-cache</code>）时，浏览器会向服务器发起请求，但会携带缓存标识，由服务器判断资源是否更新：</p><ol><li><code>ETag</code> / <code>If-None-Match</code>（优先级更高）</li></ol><ul><li>服务器首次返回资源时，生成一个唯一标识 <code>ETag: &quot;abc123&quot;</code></li><li>后续请求携带 <code>If-None-Match: &quot;abc123&quot;</code></li><li>服务器比对：未变化返回 <strong><code>304 Not Modified</code></strong>（无 body），变化则返回 <strong><code>200</code></strong> + 新资源</li></ul><ol start="2"><li><code>Last-Modified</code> / <code>If-Modified-Since</code>（HTTP/1.0）</li></ol><ul><li>服务器返回资源最后修改时间 <code>Last-Modified: Wed, 13 Aug 2026 10:00:00 GMT</code></li><li>后续请求携带 <code>If-Modified-Since: Wed, 13 Aug 2026 10:00:00 GMT</code></li><li>服务器比对时间：未变化返回 304，变化返回 200</li></ul><blockquote><p>ETag 比 Last-Modified 更精确，因为后者以秒为单位，且文件内容不变但修改时间变了会误判。</p></blockquote>`,28)])])}const g=o(d,[["render",n]]);export{u as __pageData,g as default};
